// src/lib/mcp/tools/list-projects.ts
var list_projects_default = defineTool({
  name: "list_projects",
  title: "List real estate projects",
  description: "List all Lionvest Realty real estate projects with id, name, developer, location, and short description.",
  inputSchema: {
    featuredOnly: z.boolean().optional().describe("If true, return only featured projects.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ featuredOnly }) => {
    const items = projectsData.filter((p) => featuredOnly ? p.isFeatured : true).map((p) => ({
      id: p.id,
      propertyName: p.propertyName,
      developerName: p.developerName,
      location: p.location,
      description: p.description,
      isNew: !!p.isNew,
      isFeatured: !!p.isFeatured
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { projects: items }
    };
  }
});

// src/lib/mcp/tools/get-project.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z as z2 } from "npm:zod@^4.4.3";
var get_project_default = defineTool2({
  name: "get_project",
  title: "Get project details",
  description: "Get full details for a Lionvest Realty project by id, including address, amenities, images, and specifications.",
  inputSchema: {
    id: z2.string().min(1).describe("Project id, e.g. 'aipl-joy-district'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const project = projectsData.find((p) => p.id === id);
    if (!project) {
      return {
        content: [{ type: "text", text: `No project found with id '${id}'.` }],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(project, null, 2) }],
      structuredContent: { project }
    };
  }
});

// src/lib/mcp/tools/search-projects.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z as z3 } from "npm:zod@^4.4.3";
var search_projects_default = defineTool3({
  name: "search_projects",
  title: "Search projects",
  description: "Search Lionvest Realty projects by free-text query against name, developer, location, and description.",
  inputSchema: {
    query: z3.string().min(1).describe("Search text, e.g. 'Sector 88' or 'AIPL'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query }) => {
    const q = query.toLowerCase();
    const items = projectsData.filter(
      (p) => [p.propertyName, p.developerName, p.location, p.description, p.fullAddress].filter(Boolean).some((f) => f.toLowerCase().includes(q))
    ).map((p) => ({
      id: p.id,
      propertyName: p.propertyName,
      developerName: p.developerName,
      location: p.location
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(items, null, 2) }],
      structuredContent: { results: items, count: items.length }
    };
  }
});

